class Solution:
    def findBall(self, grid: list[list[int]]) -> list[int]:
        m, n = len(grid), len(grid[0])
        result = []
        for col in range(n):
            c = col
            for row in range(m):
                nc = c + grid[row][c]
                if nc < 0 or nc >= n or grid[row][nc] != grid[row][c]:
                    c = -1
                    break
                c = nc
            result.append(c)
        return result

